-- Tobiten (扉店) Core Database Schema
-- Migration: 0001_init.sql
-- Milestone: M1A (Runtime & Security)
--
-- Identifier format decision (ADR-0001 §6, S-01):
-- Every `id TEXT PRIMARY KEY` is generated by the application as an opaque,
-- URL-safe, time-ordered RFC 9562 UUIDv7 string in canonical lowercase
-- hyphenated representation (e.g. '019318a0-0000-7000-8000-000000000001').
-- This format is fixed by this initial migration and never changed;
-- adapters expose these ids verbatim and nothing parses them.
--
-- Enumerated TEXT columns list their 1.0 values in comments; CHECK constraints
-- are added only where a wrong value would corrupt an invariant, so additive
-- values stay a data change rather than a migration.

-- Extensions (ADR-0001). Server-level compression settings live in the
-- embedded instance's generated postgresql.conf, never in migrations.
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- 0. Runtime settings (ADR-0014; M1A): layer 3 of configuration precedence and
--    home of provisioning defaults. Secrets are AES-256-GCM ciphertext when is_secret.
CREATE TABLE system_settings (
    key        TEXT PRIMARY KEY,                    -- e.g. 'oidc.default_role_id', 'events.retention_days'
    value      JSONB NOT NULL,
    is_secret  BOOLEAN NOT NULL DEFAULT FALSE,      -- value holds base64 AES-256-GCM ciphertext
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_by TEXT                                 -- FK to users added after users table; ON DELETE SET NULL
);

-- 1. Named Users & Label-Based Access Control (ADR-0006)
CREATE TABLE users (
    id         TEXT PRIMARY KEY,
    username   TEXT UNIQUE NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE system_settings ADD CONSTRAINT fk_system_settings_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL;

-- 2. Credentials (ADR-0006, ADR-0018 S1): every credential kind in one table.
--    New protocols add kinds / hash schemes, never a schema redesign.
CREATE TABLE credentials (
    id               TEXT PRIMARY KEY,               -- PATs embed this id so lookup is by id, then hash verification
    user_id          TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    kind             TEXT NOT NULL,                  -- 'PASSWORD', 'PAT', 'OIDC_LINK' (later e.g. 'KOSYNC_SECRET', 'KOBO_DEVICE_TOKEN')
    scopes           TEXT[] NOT NULL DEFAULT '{}',   -- PAT scopes: 'read', 'progress:write', 'metadata:write', 'library:admin', 'admin'; never exceed the user's role
    secret_hash      TEXT,                           -- NULL for OIDC_LINK
    hash_scheme      TEXT,                           -- e.g. 'argon2id' (later 'argon2id(md5)' for kosync)
    external_subject TEXT,                           -- OIDC issuer + subject for OIDC_LINK
    label            TEXT,                           -- user-visible name, e.g. 'Mihon on Pixel'
    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_used_at     TIMESTAMPTZ,
    expires_at       TIMESTAMPTZ,
    revoked_at       TIMESTAMPTZ,
    CHECK (kind <> 'PAT' OR cardinality(scopes) > 0)  -- empty scopes = the kind's full grant (PASSWORD); a PAT must name its scopes
);

CREATE UNIQUE INDEX idx_credentials_oidc ON credentials (external_subject) WHERE kind = 'OIDC_LINK';
CREATE UNIQUE INDEX idx_credentials_password ON credentials (user_id) WHERE kind = 'PASSWORD' AND revoked_at IS NULL;

-- 2b. Roles = named permission sets (ADR-0006). Built-ins: Admin, Curator, Reader, Restricted reader
--     (labels required); admins may add custom roles. (Core enforcement M1A; management UI/OIDC mapping M5)
CREATE TABLE roles (
    id       TEXT PRIMARY KEY,
    name     TEXT UNIQUE NOT NULL,
    built_in BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE role_permissions (
    role_id    TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    permission TEXT NOT NULL,                        -- 'library:read', 'progress:write', 'metadata:edit', 'collections:manage', 'library:admin', 'users:admin'
    PRIMARY KEY (role_id, permission)
);

CREATE TABLE user_roles (
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role_id TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    PRIMARY KEY (user_id, role_id)
);

-- 6b. Scoped labels (ADR-0006). One representation for every label:
--     SERVER labels (admin/curator) drive access restriction and trash ('marked_for_deletion');
--     USER labels are owner-private personal state ('want-to-read', 'favorite', 'dnf', custom)
--     and never affect access.
CREATE TABLE labels (
    id       TEXT PRIMARY KEY,
    scope    TEXT NOT NULL,                         -- 'SERVER', 'USER'
    owner_id TEXT REFERENCES users(id) ON DELETE CASCADE,  -- NULL for SERVER labels
    name     TEXT NOT NULL,
    built_in BOOLEAN NOT NULL DEFAULT FALSE,
    CHECK (scope IN ('SERVER', 'USER')),
    CHECK ((scope = 'SERVER') = (owner_id IS NULL))
);

CREATE UNIQUE INDEX idx_labels_server ON labels (name) WHERE scope = 'SERVER';
CREATE UNIQUE INDEX idx_labels_user ON labels (owner_id, name) WHERE scope = 'USER';

CREATE TABLE item_labels (
    label_id  TEXT NOT NULL REFERENCES labels(id) ON DELETE CASCADE,
    item_type TEXT NOT NULL CHECK (item_type IN ('SERIES', 'VOLUME', 'ASSET')),
    item_id   TEXT NOT NULL,                        -- polymorphic, no FK; purge removes rows explicitly (ADR-0010)
    PRIMARY KEY (label_id, item_type, item_id)
);

CREATE INDEX idx_item_labels_item ON item_labels (item_type, item_id);

-- Stable SERVER label identities; renames preserve policies. Reject USER labels via constraint trigger.
CREATE TABLE user_label_policies (
    user_id  TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    label_id TEXT NOT NULL REFERENCES labels(id) ON DELETE RESTRICT,
    effect   TEXT NOT NULL CHECK (effect IN ('ALLOW', 'RESTRICT')),
    PRIMARY KEY (user_id, label_id)                  -- one effect per (subject, label); RESTRICT wins across subjects/groups
);

-- Triggers enforcing that user_label_policies only ever references SERVER labels.
-- Using FOR SHARE on the label row prevents a race where a concurrent transaction
-- updates the label's scope from SERVER to USER before this policy insert commits:
-- the concurrent UPDATE will block waiting for this transaction's SHARE lock to release,
-- and upon unblocking, trg_labels_prevent_server_scope_change will see this committed policy row.
CREATE OR REPLACE FUNCTION trg_check_user_label_policy_scope()
RETURNS TRIGGER AS $$
DECLARE
    v_scope TEXT;
BEGIN
    SELECT scope INTO v_scope FROM labels WHERE id = NEW.label_id FOR SHARE;
    IF v_scope IS DISTINCT FROM 'SERVER' THEN
        RAISE EXCEPTION 'user_label_policies only permit SERVER labels, got % for label_id %', v_scope, NEW.label_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE CONSTRAINT TRIGGER trg_user_label_policies_server_only
    AFTER INSERT OR UPDATE ON user_label_policies
    DEFERRABLE INITIALLY IMMEDIATE
    FOR EACH ROW
    EXECUTE FUNCTION trg_check_user_label_policy_scope();

CREATE OR REPLACE FUNCTION trg_check_label_scope_update()
RETURNS TRIGGER AS $$
BEGIN
    IF OLD.scope = 'SERVER' AND NEW.scope <> 'SERVER' THEN
        IF EXISTS (SELECT 1 FROM user_label_policies WHERE label_id = OLD.id) THEN
            RAISE EXCEPTION 'Cannot change scope of label referenced in user_label_policies';
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE CONSTRAINT TRIGGER trg_labels_prevent_server_scope_change
    AFTER UPDATE OF scope ON labels
    DEFERRABLE INITIALLY IMMEDIATE
    FOR EACH ROW
    EXECUTE FUNCTION trg_check_label_scope_update();

-- 8. Domain Events — transactional outbox (ADR-0018 S3). Written in the same transaction as the
--    change; the dispatcher tracks a position per subscriber and delivers events as durable jobs
--    (ADR-0017), at least once. Payloads are versioned; consumers ignore unknown fields.
--    Also served by GET /api/v1/events (Last-Event-ID = published_sequence, NEVER raw id).
--    One serialized dispatcher assigns sequence + published_at to committed unsequenced rows;
--    consumers see them only after that transaction commits. Always select unpublished rows,
--    never id > last_seen: producer IDs can commit out of order. Retention uses published_at.
--    Unsequenced events are never pruned; lagging durable subscribers explicitly stall before pruning.
CREATE TABLE domain_events (
    id                 BIGSERIAL PRIMARY KEY,            -- internal identity, not a replay cursor
    published_sequence BIGINT UNIQUE,                -- NULL until serialized post-commit sequencing
    published_at       TIMESTAMPTZ,
    kind               TEXT NOT NULL,                    -- asset/progress events; job.started/finished/failed/cancelled (not EVENT_DELIVERY)
    version            INT NOT NULL DEFAULT 1,           -- payload schema version
    aggregate_type     TEXT NOT NULL,                    -- 'asset', 'volume', 'series', 'job', ...
    aggregate_id       TEXT NOT NULL,
    payload            JSONB NOT NULL DEFAULT '{}',
    created_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CHECK ((published_sequence IS NULL) = (published_at IS NULL))
);

CREATE INDEX idx_domain_events_unpublished ON domain_events (id) WHERE published_sequence IS NULL;

-- 8b. Durable subscriber cursors (ADR-0013 §3, ADR-0018 S3; M1A dispatcher). One row per durable
--     subscriber (notifier, webhook subscription, later scrobbler). Delivery advances `position`
--     only after acknowledgment or authorized filter-skip. Retention never prunes a published
--     event above the lowest ACTIVE position; an over-window subscriber becomes STALLED first.
CREATE TABLE event_subscribers (
    id         TEXT PRIMARY KEY,                    -- e.g. 'notify:shoutrrr', 'webhook:<subscription id>'
    kind       TEXT NOT NULL,                       -- subscriber module kind
    position   BIGINT NOT NULL DEFAULT 0,           -- last acknowledged published_sequence
    state      TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (state IN ('ACTIVE', 'PAUSED', 'STALLED')),
    stalled_at TIMESTAMPTZ,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CHECK ((state = 'STALLED') = (stalled_at IS NOT NULL))
);

-- 9. Durable Jobs (ADR-0017 is authoritative for semantics)
CREATE TABLE jobs (
    id               TEXT PRIMARY KEY,
    kind             TEXT NOT NULL,                  -- e.g. 'SCAN', 'INTAKE', 'REPACK', 'WRITE_BACK', 'SCRAPE', 'PURGE', 'EVENT_DELIVERY'
    state            TEXT NOT NULL DEFAULT 'QUEUED' CHECK (state IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED')),
    payload          JSONB NOT NULL DEFAULT '{}',
    checkpoint       JSONB NOT NULL DEFAULT '{}',    -- Resume point after restart
    attempts         INT NOT NULL DEFAULT 0,
    max_attempts     INT NOT NULL DEFAULT 3,
    cancel_requested BOOLEAN NOT NULL DEFAULT FALSE,
    last_error       TEXT,
    created_by       TEXT REFERENCES users(id) ON DELETE SET NULL, -- deleted creator leaves admin-only visibility
    dedupe_key       TEXT,                           -- ADR-0017 §1: e.g. 'SCAN:<library_id>'; one active job per key (idempotent 202 triggers)
    run_after        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    started_at       TIMESTAMPTZ,
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    finished_at      TIMESTAMPTZ
);

CREATE INDEX idx_jobs_runnable ON jobs (kind, run_after) WHERE state = 'QUEUED';
CREATE UNIQUE INDEX idx_jobs_active_dedupe ON jobs (dedupe_key) WHERE dedupe_key IS NOT NULL AND state IN ('QUEUED', 'RUNNING');

